const SUPPLIER_FIELD_META_LABELS={label:'字段中文名',key:'field key',type:'数据类型',required:'是否必填',editable:'是否可编辑',validation:'校验规则',source:'数据来源',factLevel:'事实等级',updatedBy:'修改人或来源主体',abnormal:'异常状态',permission:'操作权限'};
function supplierFieldValue(field,values={}){const v=values[field.key];if(v===undefined||v===null||v==='')return '待业务事实';return supplierFriendlyValue(v)}
const SUPPLIER_PRODUCT_PARADIGM={
'/property':'资料型','/content':'资料型','/direct':'资料型','/account':'资料型','/help':'资料型',
'/orders':'交易型','/fulfillment':'交易型','/refunds':'交易型','/go-offer':'交易型','/finance':'交易型','/reconciliation':'交易型','/reviews-truth':'交易型','/supplier-fault':'交易型','/t20':'交易型','/inbox':'交易型','/command':'交易型',
'/rooms':'配置型','/rates':'配置型','/go-identity':'配置型','/connectors':'配置型','/go-rating':'配置型','/vertical-capabilities':'配置型','/growth':'配置型'
};
function supplierInputControl(f,value){const ro=!String(f.editable||'').includes('供应商可编辑');const v=(value===undefined||value===null)?'':value;const type={integer:'number',decimal:'number',money:'number',date:'date',datetime:'datetime-local',time:'time',email:'email',url:'url',phone:'tel'}[f.type]||'text';if(f.type==='enum')return `<select data-business-field="${esc(f.key)}" ${ro?'disabled':''}><option>${v?esc(supplierFriendlyValue(v)):'请选择'}</option></select>`;return `<input data-business-field="${esc(f.key)}" type="${type}" value="${esc(v)}" placeholder="${esc(f.required==='是'?'必填':'选填')}" ${ro?'readonly':''}>`}
function supplierFieldTemplate(route,values={}){const fields=SUPPLIER_FIELD_SCHEMAS[route]||[];if(!fields.length)return '';const paradigm=SUPPLIER_PRODUCT_PARADIGM[route]||'资料型';const visible=fields.filter(f=>!/(编号|主键)/.test(f.label)&&f.type!=='id'&&values[f.key]!==undefined&&values[f.key]!==null&&values[f.key]!=='');if(!visible.length)return `<details class="tech-diagnostics"><summary>技术信息 / 高级信息</summary><p class="muted">字段定义仅供技术诊断使用，不作为酒店员工的主操作界面。</p></details>`;return `<section class="business-facts"><div class="section-head"><div><h3>${paradigm==='资料型'?'关键资料':paradigm==='交易型'?'关键业务事实':'关键配置'}</h3><span>仅展示当前真实业务值；内部字段定义默认隐藏</span></div></div><div class="business-facts-grid">${visible.slice(0,10).map(f=>`<div class="business-fact"><span>${esc(f.label)}</span><b>${esc(supplierFriendlyValue(values[f.key]))}</b></div>`).join('')}</div></section><details class="tech-diagnostics"><summary>技术信息 / 高级信息</summary><p class="muted">field key、数据类型、来源与事实等级仅供技术诊断。</p></details>`}
function bindSupplierProductDraft(route){}

function supplierFriendlyLabel(k){return SUPPLIER_LABELS[k]||labelize(k)}
function supplierFriendlyValue(v){return ({NOT_REGISTERED:'尚未开通',NOT_MAPPED:'尚未关联'})[String(v)]??SUPPLIER_STATE_LABELS[String(v)]??friendlyValue(v)}
function supplierActionLinks(actions=[]){return `<div class="structured-actions">${actions.map(([l,r])=>`<a class="btn" href="#${r}">${esc(l)}</a>`).join('')}</div>`}
function supplierStructuredHeader(route,metricValues={}){const b=SUPPLIER_BLUEPRINTS[route]||{title:'运营模块',subtitle:'结构化运营工作台',metrics:['当前状态'],actions:[['返回经营中心','/command']]};const keys=b.metrics||[];const cards=keys.map(k=>`<div class="card structured-metric"><div class="metric-label">${esc(k)}</div><div class="metric-value">${esc(metricValues[k]??'—')}</div><div class="metric-sub">以当前可验证事实为准</div></div>`).join('');return `<div class="section-head structured-head"><div><h2>${esc(b.title)}</h2><span>${esc(b.subtitle)}</span></div><span class="status">结构化运营</span></div><div class="grid structured-metrics">${cards}</div>`}
function supplierStructuredEmpty(route,sectionTitle='当前数据'){const b=SUPPLIER_BLUEPRINTS[route]||{};return `<section class="card structured-empty"><div class="structured-empty-icon">＋</div><div><h3>${esc(sectionTitle)}</h3><p>${esc(b.empty||'当前没有可展示的业务数据。')}</p></div>${supplierActionLinks(b.actions||[['返回经营中心','/command']])}</section>`}
function supplierStructuredShell(route,body='',metricValues={},fieldValues={}){currentSupplierRoute=route;return supplierStructuredHeader(route,metricValues)+supplierFieldTemplate(route,fieldValues)+`<div class="structured-body">${body||supplierStructuredEmpty(route)}</div>`}
function supplierPlaceholder(route,sections=[]){const body=sections.map(s=>`<section class="card structured-section"><div><h3>${esc(s)}</h3><p>当前尚无可验证数据；模块结构已就绪，后续只接入真实业务事实。</p></div><span class="status">待数据</span></section>`).join('')+supplierActionLinks((SUPPLIER_BLUEPRINTS[route]||{}).actions||[]);$('#view').innerHTML=supplierStructuredShell(route,body)}
function supplierHubCard(title,description,route,tag='进入'){return `<a class="card supplier-hub-card" href="#${route}"><div><h3>${esc(title)}</h3><p>${esc(description)}</p></div><span class="status">${esc(tag)}</span></a>`}
function supplierHubPage(route,title,subtitle,cards,noticeText='复杂能力下沉到二级页面；首页只保留高频任务与异常。'){currentSupplierRoute=route;$('#view').innerHTML=`<div class="section-head structured-head"><div><h2>${esc(title)}</h2><span>${esc(subtitle)}</span></div><span class="status">任务导向</span></div><section class="card structured-section"><div><h3>工作原则</h3><p>${esc(noticeText)}</p></div><span class="status">RC20.1</span></section><div class="grid supplier-hub-grid">${cards.map(c=>supplierHubCard(...c)).join('')}</div>`}
