async function recoveryCredentialAuthority(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/credential-authority/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Credential Issuance Authority + Hardware Trust Federation</h2><span>Trust Root · Issuer · Policy Version · Verifier Quorum · Credential Lineage · Revocation Sync</span></div>${metrics({trust_roots:r.trust_roots?.length||0,issuers:r.issuers?.length||0,policies:r.policies?.length||0,credentials:r.credential_issuances?.length||0,revocation_syncs:r.revocation_syncs?.length||0})}<div class="card"><h3>Production Admission Boundary</h3><p>Attestation PASS does not equal PROD eligibility. Runtime identities require an active governed credential issued under an active policy, trusted issuer/root and verifier quorum. Revocation removes eligibility immediately but never mutates Supplier Fact or completed transactions.</p></div><h2>Hardware Trust Roots</h2>${table(r.trust_roots||[])}<h2>Credential Issuers</h2>${table(r.issuers||[])}<h2>Attestation Policies</h2>${table(r.policies||[])}<h2>Credential Issuances</h2>${table(r.credential_issuances||[])}<h2>Revocation Synchronization</h2>${table(r.revocation_syncs||[])}`}


async function externalTrust(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/external-trust/status?environment=PROD'));const cp=r.public_checkpoint||{};$('#view').innerHTML=`<div class="section-head"><h2>External Trust Witness + Multi-Region Consensus</h2><span>Merkle Proof · Witness Co-sign · Split-View Detection · Fail-Safe Admission</span></div>${metrics({tree_size:cp.tree_size||0,witnesses:r.witnesses?.length||0,region_replicas:r.region_replicas?.length||0,policies:r.policies?.length||0,recent_decisions:r.recent_decisions?.length||0})}<div class="card"><h3>Fail-Safe Boundary</h3><p>Multi-region admission requires consistent fresh credential state, identical witnessed checkpoint, witness quorum, and local federated admission. Any regional disagreement is SPLIT_VIEW_DETECTED and fails closed; majority vote cannot override a conflicting revocation view.</p></div>${jsonCard('Witnessed Merkle Checkpoint',cp)}<h2>External Witnesses</h2>${table(r.witnesses||[])}<h2>Region Trust Replicas</h2>${table(r.region_replicas||[])}<h2>Admission Policies</h2>${table(r.policies||[])}<h2>Recent Consensus Decisions</h2>${table(r.recent_decisions||[])}`;}


async function forecastServingGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-serving/status?environment=PROD'));const b=(r.bindings||[])[0]||{},i=(r.runtime_identities||[])[0]||{},a=(r.attestations||[])[0]||{},c=(r.safety_controls||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Serving Attestation</h2><span>Deployment Provenance · Runtime Model Identity · Loaded Artifact Digest · Fail-Safe Serving Gate</span></div>${metrics({deployment:b.state||'NONE',runtime_identity:i.state||'NONE',serving_attestation:a.attestation_state||'NONE',serving_control:c.control_state||'NONE'})}<div class="card"><h3>Runtime serving boundary</h3><p>4P proves which signed model artifact is eligible for promotion. 4Q proves that the runtime actually loaded that exact artifact/build and is serving it under the governed model identity. Any digest, build-hash or runtime-fingerprint mismatch blocks the model from Forecast until a new verified serving attestation is recorded.</p></div><h2>Artifact Deployment Bindings</h2>${table(r.bindings||[])}<h2>Runtime Model Identities</h2>${table(r.runtime_identities||[])}<h2>Serving Attestations</h2>${table(r.attestations||[])}<h2>Serving Safety Controls</h2>${table(r.safety_controls||[])}`;}

async function recoveryFederatedTrust(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/federated-trust/status?environment=PROD'));const cp=r.transparency_checkpoint||{};$('#view').innerHTML=`<div class="section-head"><h2>Federated Trust + Credential Status Distribution</h2><span>Certificate Transparency · CRL/OCSP-like Freshness · Issuer Fan-out · Runtime Admission</span></div>${metrics({federations:r.federations?.length||0,admission_policies:r.admission_policies?.length||0,recent_decisions:r.recent_admission_decisions?.length||0,issuer_incidents:r.issuer_compromises?.length||0,transparency_tree_size:cp.tree_size||0})}<div class="card"><h3>Federated Admission Boundary</h3><p>Credential validity is distributed as fresh, append-only verifiable status. A signed runtime identity is admitted only when credential status is GOOD and fresh, the root is in an active trust federation, and the applicable cluster policy allows it. Issuer compromise fans out revocation immediately; these controls never mutate Supplier Fact or completed transactions.</p></div><h2>Trust Federations</h2>${table(r.federations||[])}<h2>Admission Policies</h2>${table(r.admission_policies||[])}<h2>Recent Admission Decisions</h2>${table(r.recent_admission_decisions||[])}<h2>Issuer Compromise Fan-out</h2>${table(r.issuer_compromises||[])}${jsonCard('Transparency Checkpoint',cp)}`}

async function recoveryTelemetryTrust(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust/status?environment=PROD'));const p=r.active_policy||{},t=r.latest_trust_assessment||{},ids=r.identities||[],tel=r.telemetry_governance||{};$('#view').innerHTML=`<div class="section-head"><h2>Runtime Telemetry Trust Chain</h2><span>Signed Runtime Identity · Anti-Replay · Clock Skew · Source Quorum · Incident Automation Policy</span></div>${metrics({identities:ids.length,trust:t.state||'NO_DATA',evidence:t.evidence_level||'NO_DATA',verified_sources:t.verified_source_count||0,promotion_frozen:tel.release_safety?.control?.promotion_frozen?'YES':'NO'})}<div class="card"><h3>Automation Evidence Boundary</h3><p>Only signed workload + collector identity envelopes that pass anti-replay, clock-skew and source-quorum checks may authorize automatic release safety actions. Insufficient evidence is HUMAN_REVIEW_ONLY. Telemetry trust never mutates Supplier Fact or completed transactions.</p></div><h2>Runtime / Collector Identities</h2>${table(ids)}${jsonCard('Active Incident Automation Policy',p)}${jsonCard('Latest Telemetry Trust Assessment',t)}`}


async function forecastModelStatistics(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-model-statistics/status?environment=PROD'));const p=r.active_policy||{},pr=(r.probations||[])[0]||{},rb=(r.rollback_events||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Statistical Promotion + Automated Rollback</h2><span>Significance · Effect Size · Stability · Segment Consistency · Probation</span></div>${metrics({policy_state:p.state||'NONE',alpha:p.significance_alpha??0,min_effect_pct:p.minimum_effect_size_pct??0,stability_evals:p.stability_evaluations_required??0,probation:pr.state||'NONE',rollback_to:rb.to_model_version_id||'NONE'})}<div class="card"><h3>Promotion safety boundary</h3><p>Promotion requires statistical significance, minimum effect size, rolling stability across both horizons and required segments. A promoted Challenger enters probation first; real-world degradation rolls the model role back to the previous Champion without rewriting historical forecasts or business facts.</p></div><h2>Active Policy</h2>${table(p&&p.forecast_promotion_policy_id?[p]:[])}<h2>Promotion Probations</h2>${table(r.probations||[])}<h2>Automated Rollbacks</h2>${table(r.rollback_events||[])}`;}

async function forecastDriftGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-drift/status?environment=PROD'));const p=r.active_policy||{},a=(r.drift_assessments||[])[0]||{},q=(r.retraining_requests||[])[0]||{},f=(r.refresh_pipelines||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Drift + Governed Model Refresh</h2><span>PSI · Segment Drift · Residual Drift · Retraining · Challenger Pipeline</span></div>${metrics({policy_state:p.state||'NONE',population_psi:a.population_psi??0,segment_psi:a.max_segment_psi??0,residual_drift_pct:a.residual_drift_pct??0,drift_state:a.drift_state||'NONE',refresh_state:q.state||'NONE'})}<div class="card"><h3>Governance boundary</h3><p>Drift can create a retraining request and a PENDING_APPROVAL CHALLENGER only. The challenger must still pass model approval, 4L backtest/shadow, 4M statistical promotion and probation before it can ever become Champion.</p></div><h2>Drift Assessments</h2>${table(r.drift_assessments||[])}<h2>Retraining Requests</h2>${table(r.retraining_requests||[])}<h2>Refresh Pipelines</h2>${table(r.refresh_pipelines||[])}`;}
async function forecastTrainingGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-training/status?environment=PROD'));const p=r.active_policy||{},e=(r.eligibilities||[])[0]||{},d=(r.datasets||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Training Data + Reproducible Build Governance</h2><span>Feature Registry · Dataset Snapshot · Data Quality · Lineage · Build Hash · Reproducibility</span></div>${metrics({policy_state:p.state||'NONE',minimum_rows:p.minimum_training_rows||0,dataset_rows:d.row_count||0,latest_build_state:e.eligibility_state||'NONE'})}<div class="card"><h3>Promotion boundary</h3><p>When 4O policy is active, a Challenger cannot enter 4L backtest unless training data quality is PASS, lineage is complete, the training manifest has a deterministic build hash, and an independent reproducibility check MATCHES.</p></div><h2>Feature Versions</h2>${table(r.features||[])}<h2>Dataset Snapshots</h2>${table(r.datasets||[])}<h2>Build Eligibility</h2>${table(r.eligibilities||[])}`;}

async function forecastArtifactGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-artifacts/status?environment=PROD'));const p=r.active_policy||{},a=(r.artifacts||[])[0]||{},b=(r.bindings||[])[0]||{},i=(r.integrity||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Artifact Supply-Chain Governance</h2><span>Artifact Digest · SBOM · Signed Build Attestation · Promotion Binding · Tamper Detection</span></div>${metrics({policy_state:p.state||'NONE',latest_artifact:a.state||'NONE',package_format:a.package_format||'—',integrity_state:i.integrity_state||'NONE',promotion_binding:b.binding_state||'NONE'})}<div class="card"><h3>Production artifact boundary</h3><p>4O proves the build is reproducible; 4P proves the exact package entering 4L/4M is the artifact produced by that governed build. An active 4P policy requires artifact digest + SBOM/provenance + verified signed build attestation + fresh integrity PASS + promotion binding. Any later digest/build-hash mismatch removes promotion eligibility without rewriting historical artifact evidence.</p></div><h2>Model Artifact Registry</h2>${table(r.artifacts||[])}<h2>Promotion Bindings</h2>${table(r.bindings||[])}<h2>Integrity Assessments</h2>${table(r.integrity||[])}`;}

async function route(){notice('');const path=location.hash.slice(1)||nav[0].route;document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===path));const item=routeCatalog.find(x=>x.route===path)||nav[0];$('#pageTitle').textContent=item.label;try{if(item.custom==='supplierOrders')return supplierOrders();if(item.custom==='supplierRisks')return supplierRisks();if(item.custom==='supplierLiabilities')return supplierLiabilities();if(item.custom==='adminJudgments')return adminJudgments();if(item.custom==='adminSettlement')return adminSettlement();if(item.custom==='adminConnectors')return adminConnectors();if(item.custom==='approvals')return approvalsPage();if(item.custom==='recoveryControl')return recoveryControl();if(item.custom==='recoveryExperiments')return recoveryExperiments();if(item.custom==='recoveryLearning')return recoveryLearning();if(item.custom==='recoveryDataGovernance')return recoveryDataGovernance();if(item.custom==='recoveryLearningIncidents')return recoveryLearningIncidents();if(item.custom==='recoveryReleases')return recoveryReleases();if(item.custom==='recoveryRuntimeSafety')return recoveryRuntimeSafety();if(item.custom==='recoveryTelemetryGovernance')return recoveryTelemetryGovernance();if(item.custom==='recoveryTelemetryTrust')return recoveryTelemetryTrust();if(item.custom==='recoveryIdentityLifecycle')return recoveryIdentityLifecycle();if(item.custom==='recoveryIdentityReissuance')return recoveryIdentityReissuance();if(item.custom==='recoveryCredentialAuthority')return recoveryCredentialAuthority();if(item.custom==='recoveryFederatedTrust')return recoveryFederatedTrust();if(item.custom==='externalTrust')return externalTrust();if(item.custom==='trustGossip')return trustGossip();if(item.custom==='trustPlaneDR')return trustPlaneDR();if(item.custom==='trustChaosReadiness')return trustChaosReadiness();if(item.custom==='continuousChaosWaivers')return continuousChaosWaivers();if(item.custom==='waiverExposureDebt')return waiverExposureDebt();if(item.custom==='exceptionDebtBurndown')return exceptionDebtBurndown();if(item.custom==='enterpriseRiskPortfolio')return enterpriseRiskPortfolio();if(item.custom==='enterpriseRiskAppetite')return enterpriseRiskAppetite();if(item.custom==='enterpriseRiskForecast')return enterpriseRiskForecast();if(item.custom==='riskForecastCalibration')return riskForecastCalibration();if(item.custom==='forecastModelGovernance')return forecastModelGovernance();if(item.custom==='forecastModelStatistics')return forecastModelStatistics();if(item.custom==='forecastDriftGovernance')return forecastDriftGovernance();if(item.custom==='forecastTrainingGovernance')return forecastTrainingGovernance();if(item.custom==='forecastArtifactGovernance')return forecastArtifactGovernance();if(item.custom==='forecastServingGovernance')return forecastServingGovernance();if(item.custom==='audit')return auditPage();return generic(item)}catch(e){notice(e.message,true)}}
const ADMIN_TERM_MAP={'暂无数据':'当前没有需要处理的业务记录','Evidence':'证据','Remediation':'整改记录','Recent Economics Evidence':'近期经营分析','Forecast':'预测','Risk':'风险','Supplier':'供应商','Orders':'订单','Refunds':'退款','Settlement':'结算','Status':'状态','State':'状态'};
function adminProductizeView(route,label){if(config.actorType!=='GO_ADMIN')return;const view=$('#view');if(!view)return;if(!view.querySelector('.productized-admin-head'))view.insertAdjacentHTML('afterbegin',`<section class="productized-admin-head"><div><h2>${esc(label||'运营模块')}</h2><p>当前状态 → 核心指标 → 业务对象 → 待办异常 → 可执行动作 → 状态与审计</p></div><span class="status">运营工作台</span></section>`);view.querySelectorAll('.empty').forEach(x=>{x.outerHTML=adminEmpty('当前没有需要处理的业务记录')});view.querySelectorAll('pre.mono.pre').forEach(pre=>{const d=pre.closest('details');if(!d){const wrap=document.createElement('details');wrap.className='card tech-diagnostics';wrap.innerHTML='<summary>技术信息 / 原始数据</summary>';pre.replaceWith(wrap);wrap.appendChild(pre)}});view.querySelectorAll('h2,h3').forEach(h=>{const map={Requirements:'需求',Prebook:'预订前核验','Prebook Revalidation':'预订前重新核验','Order Handoffs':'订单交接','责任事件':'供应商责任事件',Liabilities:'赔付责任','保障资金记录':'保障资金记录',Subscriptions:'订阅状态','有效订单证据':'有效订单证据',Invoices:'账单',Waivers:'豁免申请',Credential:'身份凭证'};if(map[h.textContent.trim()])h.textContent=map[h.textContent.trim()]});if(!view.querySelector('.admin-ops-bar'))view.insertAdjacentHTML('beforeend',adminOpsBar());bindAdminOps()}
function installAdminProductizationObserver(){if(config.actorType!=='GO_ADMIN')return;const v=$('#view');if(!v)return;const ob=new MutationObserver(()=>{const item=routeCatalog.find(x=>x.route===(location.hash.slice(1)||nav[0].route))||nav[0];adminProductizeView(item.route,item.label)});ob.observe(v,{childList:true,subtree:true});adminProductizeView(nav[0].route,nav[0].label)}
(async()=>{try{me=unwrap(await api.me());if(config.actorType&&me.actor_type!==config.actorType)throw new Error('WRONG_ACTOR');shell();queueMicrotask(installAdminProductizationObserver)}catch{loginView()}})();
async function recoveryDataGovernance(){const [q,m,b,k,z]=await Promise.all(['/internal/v1/recovery/learning/data-quality','/internal/v1/recovery/learning/supplier-mappings','/internal/v1/recovery/learning/privacy-budgets','/internal/v1/recovery/learning/kill-switches','/internal/v1/recovery/learning/quarantine'].map(x=>api.request(x).then(unwrap)));const qs=q.items||[],ks=k.items||[];$('#view').innerHTML=`<div class="section-head"><h2>Recovery Data Governance</h2><span>Data Quality · Supplier Identity · Privacy Budget · Learning Kill Switch</span></div>${metrics({quality_pass:qs.filter(x=>x.quality_state==='PASS').length,quarantined:qs.filter(x=>x.quality_state==='QUARANTINED').length,kill_switches:ks.filter(x=>x.enabled).length,privacy_scopes:(b.items||[]).length})}<div class="actionbar"><button class="btn primary" id="dqTick">Run Data Quality Gate</button><button class="btn" id="globalStop">Emergency: Baseline Only</button><button class="btn" id="incidentControl">Open Incident Change Control</button></div><h2>Data Quality</h2>${table(qs)}<h2>Supplier Identity Mapping</h2>${table(m.items||[])}<h2>Privacy Budget</h2>${table(b.items||[])}<h2>Learning Kill Switches</h2>${table(ks)}<h2>Quarantine</h2>${table(z.items||[])}`;$('#dqTick').onclick=async()=>{await api.request('/internal/v1/recovery/learning/data-quality/tick',{method:'POST'});recoveryDataGovernance()};$('#globalStop').onclick=()=>consoleSheet({title:'Emergency: Baseline Only',description:'进入全局基线保护状态，需要原因和后续治理证据。',fields:[{id:'baselineReason',label:'Incident 原因'}],confirmLabel:'进入 Baseline Only',danger:true,onConfirm:async v=>{await api.request('/internal/v1/recovery/learning/incidents',{method:'POST',body:{scope_type:'GLOBAL',scope_key:'*',severity:'SEV1',reason:v.baselineReason}});location.hash='/recovery-learning-incidents'}});$('#incidentControl').onclick=()=>{location.hash='/recovery-learning-incidents'}}


async function trustPlaneDR(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Witness Independence + Trust Plane Disaster Recovery</h2><span>Operator Diversity · Failure Domains · Cross-Operator Gossip · Archive/Rebuild · DR Drill</span></div>${metrics({operators:r.operators?.length||0,active_policies:r.active_policies?.length||0,recent_assessments:r.recent_assessments?.length||0,disasters:r.disasters?.length||0})}<div class="card"><h3>Independence Boundary</h3><p>Witness quorum is counted by independent operators and failure domains, not by raw process count. The same operator, cloud or key authority cannot manufacture quorum. Open Region/Provider trust-plane disasters fail safe until every affected region has a verified archive rebuild under independent witness governance.</p></div><h2>Witness Operators</h2>${table(r.operators||[])}<h2>Independence Policies</h2>${table(r.active_policies||[])}<h2>Recent Independence Assessments</h2>${table(r.recent_assessments||[])}<h2>Trust Plane Disasters / Drills</h2>${table(r.disasters||[])}`}
async function trustGossip(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-gossip/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Transparency Gossip + Trust Recovery</h2><span>Witness Federation · Split-View Incident · Region Isolation · Rejoin</span></div>${metrics({isolated_regions:r.isolated_regions?.length||0,incidents:r.incidents?.length||0,witness_federations:r.witness_federations?.length||0,recoveries:r.recoveries?.length||0})}<div class="card"><h3>Fail-Safe Recovery Boundary</h3><p>Checkpoint gossip detects divergent views. Split-view opens a SEV1 incident and isolates affected regions. Rejoin requires verified consistency proof plus witness-federation quorum; majority vote never overrides conflicting trust state.</p></div>${jsonCard('Isolated Regions',r.isolated_regions||[])}<h2>Split-View Incidents</h2>${table(r.incidents||[])}<h2>Witness Federations</h2>${table(r.witness_federations||[])}<h2>Trust Recoveries</h2>${table(r.recoveries||[])}`;}


