async function waiverExposureDebt(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/waiver-exposure/status?environment=PROD'));const d=r.exception_debt||{};$('#view').innerHTML=`<div class="section-head"><h2>Waiver Exposure + Exception Debt</h2><span>Budget · Debt · Remediation SLA · Escalation</span></div>${metrics({debt_state:d.debt_state||'NOT_GOVERNED',debt_points:d.debt_points??0,rolling_waivers:d.rolling_waiver_count??0,exposure_seconds:d.exposure_seconds??0})}<div class="card"><h3>Exception boundary</h3><p>New PROD waivers are blocked when rolling waiver count, consecutive waiver releases, cumulative exposure time, or exception debt exceeds policy. Every governed waiver must have a remediation owner and SLA.</p></div><h2>Exposure Policy</h2>${table(r.policy?[r.policy]:[])}<h2>Exception Debt</h2>${table(d&&d.exception_debt_id?[d]:[])}<h2>Remediation Cases</h2>${table(r.remediations||[])}<h2>Exposure Events</h2>${table(r.events||[])}`}

async function exceptionDebtBurndown(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/exception-debt/burn-down/status?environment=PROD'));const a=r.aging||{},f=(r.freezes||[])[0]||{},p=(r.plans||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Exception Debt Burn-Down + Executive Risk Governance</h2><span>Debt Aging · Waiver Freeze · Milestones · RACI · Residual Risk</span></div>${metrics({aging_state:a.aging_state||'NO_DATA',debt_points:a.debt_points??0,freeze:f.state||'NONE',plan_progress:p.progress_percent??0})}<div class="card"><h3>Governance boundary</h3><p>High or aged exception debt activates a waiver freeze. Executive Risk Acceptance is time-bound and maker-checker governed; it does not bypass the freeze or become a higher-level waiver. Freeze release still requires debt reduction, or a completed burn-down plan plus active residual-risk acceptance.</p></div><h2>Debt Aging</h2>${table(a&&a.debt_aging_assessment_id?[a]:[])}<h2>Burn-Down Plans + Milestones / RACI</h2>${table(r.plans||[])}<h2>Waiver Freezes</h2>${table(r.freezes||[])}<h2>Executive Risk Acceptances</h2>${table(r.executive_acceptances||[])}<h2>Governance Events</h2>${table(r.events||[])}`}

