let supplierSelectedPropertyId=null,supplierPropertyRows=[],supplierRequestsPending=0,supplierImportBusy=false,supplierBuildSequence=0;
const supplierImportDrafts=new Map();
let supplierCaptureImportDraft=null;
function supplierChooseProperty(rows){
 supplierPropertyRows=Array.isArray(rows)?rows:[];
 const selected=supplierPropertyRows.find(p=>p.property_id===supplierSelectedPropertyId)||supplierPropertyRows[0]||null;
 supplierSelectedPropertyId=selected?.property_id||null;
 const selector=$('#supplierPropertySelect');
 if(selector){selector.innerHTML=supplierPropertyRows.map(p=>`<option value="${esc(p.property_id)}" ${p.property_id===supplierSelectedPropertyId?'selected':''}>${esc(p.name_zh||p.property_id)}</option>`).join('');selector.disabled=!selected;selector.value=supplierSelectedPropertyId||'';selector.onchange=()=>supplierSwitchProperty(selector.value)}
 return selected;
}
async function supplierSwitchProperty(id){
 const selector=$('#supplierPropertySelect');
 if(!supplierPropertyRows.some(p=>p.property_id===id))return false;
 if(supplierRequestsPending||supplierImportBusy){if(selector)selector.value=supplierSelectedPropertyId;notice('当前操作尚未结束，请完成后再切换酒店。',true);return false}
 supplierCaptureImportDraft?.();supplierCaptureImportDraft=null;
 supplierSelectedPropertyId=id;
 if(selector)selector.value=id;
 await route();return true;
}
function supplierRoomMappings(pack,rooms){
 const sources=pack.room_types||[];
 if(!sources.some(r=>Object.hasOwn(r,'source_room_id'))&&!Object.hasOwn(pack,'room_mappings'))return null;
 const seen=new Set(),targets=new Set();
 return sources.map((room,i)=>{
  const sid=room.source_room_id,choice=$('#roomMap'+i)?.value,confirmed=$('#roomMapConfirm'+i)?.checked;
  if(typeof sid!=='string'||!sid.trim()||seen.has(sid)||!confirmed||!choice)throw new Error('ROOM_MAPPING_CONFIRMATION_REQUIRED');
  seen.add(sid);
  if(choice==='__CREATE__')return {source_room_id:sid,action:'CREATE',confirmed:true};
  if(!rooms.some(r=>r.room_type_id===choice)||targets.has(choice))throw new Error('ROOM_MAPPING_CONFIRMATION_REQUIRED');
  targets.add(choice);return {source_room_id:sid,target_room_type_id:choice,confirmed:true};
 });
}
const supplierOriginalRequest=api.request.bind(api);
api.request=async function(...args){supplierRequestsPending++;try{return await supplierOriginalRequest(...args)}finally{supplierRequestsPending--}};
const HOTEL_IMPORT_FIELDS={'hotel.name_zh':'酒店中文名','hotel.name_en':'酒店英文名','hotel.property_type':'酒店类型','hotel.group_name':'集团','hotel.brand_name':'品牌','hotel.address':'地址','hotel.contacts':'联系方式','hotel.legal':'资质','hotel.poi':'周边位置','room_types':'房型'};
function hotelImportError(error){
 const code=String(error?.message||'');
 const labels={IMPORT_SELECTION_REQUIRED:'请至少选择一项资料。',IMPORT_SELECTED_FIELD_MISSING:'所选资料已变化，请重新预览。',INVALID_IMPORT_SELECTION:'所选资料无法导入，请重新预览。',HOTEL_DATA_PACKAGE_REQUIRED:'请提供酒店资料包。',HOTEL_DATA_PACKAGE_INVALID:'资料格式不正确，请检查后重试。',ROOM_MAPPING_CONFIRMATION_REQUIRED:'请逐项核对对应关系，选择GO房型或新建，并勾选确认；不能重复映射到同一房型。',INVALID_ROOM_TYPE:'房型资料不完整，请检查名称和房量。',INVALID_OCCUPANCY_CONSTRAINT:'房型入住人数不完整，请核对。',OTA_CREDENTIALS_NOT_ACCEPTED:'请移除资料中的账号密码、验证码或访问凭据。',MEDIA_IMAGE_TOO_SMALL:'图片清晰度不足，请使用短边至少720、长边至少1280像素的高清文件。',MEDIA_IMAGE_TOO_LARGE:'图片超过15MB，请选择较小的高清文件。',MEDIA_CONTENT_NOT_VALID_IMAGE:'文件不是可读取的图片，请重新选择。',MEDIA_IMAGE_FORMAT_NOT_ALLOWED:'请选择JPEG、PNG或WEBP图片。',MEDIA_IMAGE_PIXEL_LIMIT:'图片超过4000万像素，请调整后重试。',MEDIA_RIGHTS_EVIDENCE_REQUIRED:'请填写图片权利人和授权依据。',MEDIA_RIGHTS_EXPIRED:'图片授权已过期，请更新授权依据。',PROPERTY_NOT_FOUND:'酒店资料不可用，请确认当前酒店。',ROOM_TYPE_NOT_FOUND:'房型不可用，请重新选择。'};
 return labels[code]||'操作未完成，输入和选择已保留，请核对后重试。';
}
function hotelImportPreview(raw){
 let pack;try{pack=JSON.parse(raw)}catch{throw new Error('HOTEL_DATA_PACKAGE_INVALID')}
 if(!pack||typeof pack!=='object'||Array.isArray(pack))throw new Error('HOTEL_DATA_PACKAGE_INVALID');
 if(Object.hasOwn(pack,'room_types')&&(!Array.isArray(pack.room_types)||pack.room_types.some(room=>!room||typeof room!=='object'||Array.isArray(room))))throw new Error('HOTEL_DATA_PACKAGE_INVALID');
 const fields=Object.entries(HOTEL_IMPORT_FIELDS).filter(([key])=>key==='room_types'?Object.hasOwn(pack,key):pack.hotel&&typeof pack.hotel==='object'&&!Array.isArray(pack.hotel)&&Object.hasOwn(pack.hotel,key.slice(6)));
 return {pack,fields};
}
function hotelSelectedPackage(pack,selected){
 const result={};
 for(const key of selected){if(key==='room_types'){result.room_types=(pack.room_types||[]).map(room=>{const {media,media_json,...facts}=room;return facts})}else{result.hotel||={};result.hotel[key.slice(6)]=pack.hotel[key.slice(6)]}}
 return result;
}
function supplierManifestPreview(raw,property,rooms){
 let m;try{m=JSON.parse(raw)}catch{throw new Error('清单文件格式不正确。')}
 if(!m||m.schema!=='HOTEL_DIRECT_SUBMISSION_V1'||!m.identity||!Array.isArray(m.room_mappings)||!Array.isArray(m.assets)||!m.inventory)throw new Error('请选择完整的酒店审核清单文件。');
 if(m.identity.property_id!==property.property_id||(property.supplier_id&&m.identity.supplier_id!==property.supplier_id))throw new Error('清单不属于当前酒店，请切换到对应酒店。');
 if(!m.room_mappings.length||!m.assets.length||!m.inventory.complete_confirmed)throw new Error('清单缺少完整房型或图片，请先补齐资料。');
 const seen=new Set(),targets=new Set();
 for(const r of m.room_mappings){if(!r||!r.confirmed||!r.canonical_room_id||!rooms.some(x=>x.room_type_id===r.partner_room_id)||seen.has(r.partner_room_id)||targets.has(r.canonical_room_id))throw new Error('房型对应不完整、重复或不属于当前酒店，请核对。');seen.add(r.partner_room_id);targets.add(r.canonical_room_id)}
 if(rooms.some(r=>!seen.has(r.room_type_id)))throw new Error('清单未覆盖当前酒店全部房型，请核对。');
 if(m.assets.some(a=>!a||a.property_id!==property.property_id||a.supplier_id!==m.identity.supplier_id||a.canonical_hotel_id!==m.identity.canonical_hotel_id||!a.rights||(a.role==='ROOM'&&!m.room_mappings.some(r=>r.partner_room_id===a.partner_room_id&&r.canonical_room_id===a.canonical_room_id))))throw new Error('图片所属酒店、房型或授权资料不完整，请核对。');
 return m;
}
function supplierManifestSummary(m,rooms){
 const id=m.identity,cell=x=>`<td style="overflow-wrap:anywhere">${esc(x??'待核对')}</td>`;
 return `<h4>酒店身份</h4><p>酒店编号：${esc(id.property_id)} · 正式酒店编号：${esc(id.canonical_hotel_id)} · 登记编号：${esc(id.registration_id)}</p><p>关联依据：${esc(id.association_evidence_reference)}</p><h4>房型对应（${m.room_mappings.length}）</h4><div style="overflow-x:auto"><table><thead><tr><th>酒店房型</th><th>正式房型</th><th>核对依据</th></tr></thead><tbody>${m.room_mappings.map(r=>`<tr>${cell(rooms.find(x=>x.room_type_id===r.partner_room_id)?.name_zh||r.partner_room_id)}${cell(r.canonical_room_id)}${cell(r.evidence_reference)}</tr>`).join('')}</tbody></table></div><h4>原图与授权（${m.assets.length}）</h4><p>以下是清单声明；原图文件、当前授权及资料冲突仍由服务端核验。</p><div style="overflow-x:auto"><table><thead><tr><th>图片编号 / 用途</th><th>原图尺寸</th><th>权利人</th><th>授权依据</th><th>授权截止</th></tr></thead><tbody>${m.assets.map(a=>`<tr>${cell(a.asset_id+' / '+a.role)}${cell(a.width+'×'+a.height)}${cell(a.rights.rights_holder)}${cell(a.rights.evidence_reference)}${cell(a.rights.expires_at||'未声明到期时间')}</tr>`).join('')}</tbody></table></div>`;
}
function supplierTrustedReviewPanel(){return `<section class="card"><h3>正式酒店、房型与图片审核</h3><p>上传已整理的审核清单文件，核对后提交管理员审核。清单需要正式酒店登记、完整物理房型对应、酒店高清原图及授权依据；来源平台房型和图片数量不会自动认定为正式资料。</p><p>尚无清单时，请先由资料整理人员完成上述核对。本入口不会自动生成对应关系或批准图片授权。</p><label>审核清单文件<input id="directManifestFile" type="file" accept=".json,application/json"></label><div id="directManifestPreview" aria-live="polite"></div><label><input id="directManifestConfirm" type="checkbox">已核对当前酒店、全部物理房型及图片授权资料</label><button class="btn primary" id="submitDirectManifest" disabled>提交正式审核</button><p id="directManifestStatus" role="status"></p><button class="btn" id="refreshDirectReviews">刷新审核与发布状态</button><div id="directReviews" aria-live="polite"></div></section>`}
