 $('#uploadHotelMedia').onclick=async()=>{
  if(uploading||supplierImportBusy||!isCurrent())return;const file=$('#hotelMediaFile').files?.[0],status=$('#hotelMediaStatus');
  if(!file){status.textContent='请先选择高清图片文件。';return}
  if(file.size>15*1024*1024){status.textContent='图片超过15MB，请选择较小的高清文件。';return}
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status.textContent='请选择JPEG、PNG或WEBP图片。';return}
  const holder=$('#hotelMediaHolder').value.trim(),evidence=$('#hotelMediaEvidence').value.trim(),role=$('#hotelMediaRole').value,roomId=$('#hotelMediaRoom').value;
  if(role==='ROOM'&&!rooms.some(r=>r.room_type_id===roomId)){status.textContent='请为房型图片选择当前酒店的房型。';return}
  if(!holder||!evidence||!$('#hotelMediaRights').checked){status.textContent='请填写图片权利人、授权依据并确认展示权利。';return}
  uploading=true;supplierImportBusy=true;$('#uploadHotelMedia').disabled=true;status.textContent='正在上传并核验图片，请稍候。';
  try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('READ_FAILED'));reader.readAsDataURL(file)});
   if(!isCurrent())return;
   const x=unwrap(await api.request(endpoint+'/media-uploads',{method:'POST',body:{content_base64:content,role,...(role==='ROOM'?{room_type_id:roomId}:{}),rights:{rights_holder:holder,evidence_reference:evidence,usage_scope:['DISTRIBUTE_ON_GO']}}}));
   if(!isCurrent())return;
   if(!x?.asset_id||x.state!=='DRAFT'||x.publishable!==false||!Number.isInteger(x.width)||x.width<=0||!Number.isInteger(x.height)||x.height<=0)throw new Error('UPLOAD_NOT_CONFIRMED');
   status.textContent=`${x.deduplicated?'该图片已存在':'上传成功'}：${x.width}×${x.height}像素，已存为草稿，尚未发布。`;
  }catch(e){status.textContent=hotelImportError(e)}finally{uploading=false;supplierImportBusy=false;if(isCurrent())$('#uploadHotelMedia').disabled=false}
 };
