   $('#hotelMediaList').innerHTML=mediaAssets.map((asset,i)=>`<fieldset><legend>${esc(asset.width)}×${esc(asset.height)}像素 · ${asset.bound?'已绑定':'待绑定'} · ${asset.rights_approved?'授权已核验':'授权待核验'}</legend><label><input type="checkbox" data-publish-media value="${esc(asset.asset_id)}">选择提交审核</label><label>用途<select id="mediaBindRole${i}"><option value="GALLERY" ${asset.role==='GALLERY'?'selected':''}>酒店图库</option><option value="HERO" ${asset.role==='HERO'?'selected':''}>酒店首图</option><option value="ROOM" ${asset.role==='ROOM'?'selected':''}>房型图片</option></select></label><label>房型<select id="mediaBindRoom${i}"><option value="">不绑定房型</option>${rooms.map(r=>`<option value="${esc(r.room_type_id)}" ${r.room_type_id===asset.room_type_id?'selected':''}>${esc(r.name_zh)}</option>`).join('')}</select></label><button class="btn" id="mediaBindSave${i}">保存图片绑定</button></fieldset>`).join('')||'<p>当前酒店尚无上传图片。</p>';
