    <div class="business-facts-grid"><div class="business-fact"><span>网页状态</span><b>${esc(supplierFriendlyValue(w.publication_state||'NOT_MAPPED'))}</b></div><div class="business-fact"><span>GO 直连</span><b>${esc(supplierFriendlyValue(w.go_direct_state||'NOT_REGISTERED'))}</b></div><div class="business-fact"><span>资料完整度</span><b>${prof.completeness_bps!==undefined?Math.round(Number(prof.completeness_bps)/100)+'%':'待核验'}</b></div><div class="business-fact"><span>网页版本</span><b>${esc(w.page_version||'—')}</b></div></div>
