  $('#view').innerHTML=supplierStructuredShell('/benefits',body,{'权益状态':v?'已配置':'待配置','现金价优':v.cash_discount_bps?`${Number(v.cash_discount_bps)/100}%`:'无','早餐':supplierFriendlyValue(v.breakfast_option||'NONE'),'礼遇':(v.benefits||[]).length});
