  const cards=PROMOTIONS.map(([key,name,group])=>{const row=promo.find(x=>x.policy_type===key),r=policyRule(row);return `<article class="card promo-card"><div class="section-head"><div><h3>${esc(name)}</h3><span>${esc(group)}</span></div><span class="status">${r.enabled?'已启用':'未启用'}</span></div><p>${r.enabled?`优惠 ${Number(r.discount_bps||0)/100}% · ${esc(r.start_date||'长期')} 至 ${esc(r.end_date||'长期')}`:'酒店自主决定是否开启，不影响 GO 推荐排名。'}</p><button class="btn" data-promo="${key}" data-name="${esc(name)}">设置</button></article>`}).join('');
  $('#view').innerHTML=supplierStructuredShell('/marketing',`<section class="card structured-section"><div><h3>自主促销原则</h3><p>促销只改变酒店自己授权的价格/条件；不购买推荐、不虚构“同行提升”，最终效果只使用酒店自己的真实数据评估。</p></div><span class="status">酒店自主</span></section><div class="grid promo-grid">${cards}</div>`,{'启用促销':promo.filter(x=>policyRule(x).enabled).length,'基础促销':promo.filter(x=>x.policy_type==='PROMOTION_DAILY_DEAL'&&policyRule(x).enabled).length,'场景促销':promo.filter(x=>x.policy_type!=='PROMOTION_DAILY_DEAL'&&policyRule(x).enabled).length,'待核验':promo.filter(x=>!x.updated_at).length});
  document.querySelectorAll('[data-promo]').forEach(b=>b.onclick=()=>supplierPromotionEditor(p,b.dataset.promo,b.dataset.name,promo.find(x=>x.policy_type===b.dataset.promo)));
