// Catch both synchronous missing handlers and asynchronous reads. A failed route
// must replace stale content and offer recovery rather than silently doing nothing.
const partnerDispatch=route;
route=async function(){
 const path=location.hash;
 const propertyScope=$('#supplierPropertySelect')?.closest('label');
 // These workspaces read the supplier's records across properties. A hotel
 // selector here would falsely imply that it filters non-hotel transactions.
 if(propertyScope)propertyScope.hidden=path.startsWith('#/business-')||['#/refunds','#/fulfillment','#/vertical-capabilities','#/go-identity'].includes(path);
 try{
  if(config.actorType==='SUPPLIER_USER'&&path.startsWith('#/business-')){
   const vertical=path.slice('#/business-'.length).toUpperCase();
   if(PARTNER_VERTICALS[vertical]){$('#pageTitle').textContent=PARTNER_VERTICALS[vertical]+'工作台';notice('');return await renderRecords(partnerContext(),{vertical})}
  }
  return await partnerDispatch();
 }catch(error){
  if(location.hash!==path)return;
  $('#view').innerHTML='<section class="card"><h2>页面暂时无法打开</h2><p role="alert">读取未完成，请重新加载。若仍失败，可返回经营中心继续处理其他业务。</p><button class="btn" id="retryPartnerRoute">重新加载</button><a class="btn" href="#/command">返回经营中心</a></section>';
  $('#retryPartnerRoute').onclick=()=>route();
 }
};
